<?php

defined('BASEPATH') or exit('No direct script access allowed');

class Enterprise_schema
{
    public static function install()
    {
        $CI = &get_instance();
        $prefix = db_prefix();
        $charset = preg_replace('/[^a-zA-Z0-9_]/', '', (string) ($CI->db->char_set ?: 'utf8'));
        $collation = preg_replace('/[^a-zA-Z0-9_]/', '', (string) ($CI->db->dbcollat ?: 'utf8_general_ci'));
        $oldDebug = $CI->db->db_debug;
        $CI->db->db_debug = false;

        $tables = self::definitions();
        foreach ($tables as $suffix => $definition) {
            $table = $prefix . $suffix;
            if ($CI->db->table_exists($table)) {
                continue;
            }
            $sql = "CREATE TABLE IF NOT EXISTS `{$table}` ({$definition}) ENGINE=InnoDB DEFAULT CHARSET={$charset} COLLATE={$collation}";
            if ($CI->db->query($sql) === false) {
                $error = $CI->db->error();
                log_message('error', 'Smart Choice Enterprise schema failed for ' . $table . ': ' . ($error['message'] ?? 'Unknown database error'));
            }
        }
        $CI->db->db_debug = $oldDebug;
        self::seedFeatureFlags();
        self::setOptions();
        return true;
    }

