            'sce_login_audit' => "`id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,`staff_id` INT DEFAULT NULL,`email` VARCHAR(191) DEFAULT NULL,`ip_address` VARCHAR(45) DEFAULT NULL,`user_agent` VARCHAR(500) DEFAULT NULL,`status` VARCHAR(30) NOT NULL,`occurred_at` DATETIME NOT NULL,PRIMARY KEY (`id`),KEY `staff_occurred` (`staff_id`,`occurred_at`)",
