    }

    private static function seedFeatureFlags()
    {
        $CI = &get_instance();
        $table = db_prefix() . 'sce_feature_flags';
        if (!$CI->db->table_exists($table)) return;
        $flags = [
            ['enterprise_foundation','Enterprise Foundation','Shared services, queue, audit, API and permissions.',1],
            ['customer_360','Customer 360','Customer timeline, properties, household and scoring.',1],
            ['sales_operations','Sales Operations','Opportunities, forecasting, goals and commissions.',1],
            ['field_operations','Field Operations','Visits, crews, time clock and daily logs.',1],
            ['dispatch','Dispatch','Assignments, routes and technician skills.',1],
            ['equipment_inventory','Equipment and Inventory','Equipment history, locations, stock and movements.',1],
            ['project_controls','Project Controls','Phases, RFIs, submittals, permits and change orders.',1],
            ['document_center','Document Center','Document version and approval foundation.',1],
            ['enterprise_api','Enterprise API Foundation','Disabled until an API client is explicitly created.',0],
            ['communications','Communications','Unified communication timeline and channel records.',1],
            ['call_center','Call Center','Twilio calling, call logs and recording metadata.',1],
            ['marketing','Marketing','Campaigns, attribution and review requests.',1],
            ['workflows','Workflow Automation','Triggers, steps, runs and scheduled execution.',1],
            ['reporting','Reporting','Report definitions and scheduled delivery.',1],
            ['qr_center','QR Code Center','Static and dynamic QR generation and tracking.',1],
            ['security_center','Security Center','Security rules, login history and field policies.',1],
            ['performance_center','Performance Center','Runtime, queue and database health metrics.',1],
        ];
        foreach ($flags as $flag) {
            $exists = $CI->db->where('feature_key',$flag[0])->where('scope_type','global')->get($table)->row();
            if (!$exists) $CI->db->insert($table,['feature_key'=>$flag[0],'name'=>$flag[1],'description'=>$flag[2],'is_enabled'=>$flag[3],'scope_type'=>'global','scope_id'=>null,'created_by'=>function_exists('get_staff_user_id')?(get_staff_user_id()?:null):null,'created_at'=>date('Y-m-d H:i:s')]);
        }
    }

    private static function setOptions()
    {
        $options = ['smart_choice_enterprise_core_enabled'=>'1','smart_choice_enterprise_core_version'=>'1.5.0','smart_choice_enterprise_queue_batch_size'=>'10','smart_choice_enterprise_queue_max_attempts'=>'3'];
        foreach ($options as $name=>$value) {
            if (get_option($name)==='') add_option($name,$value); else update_option($name,$value);
        }
    }
}
